CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,email VARCHAR(190) NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','user') NOT NULL DEFAULT 'user',status ENUM('active','banned','disabled') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE domains(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,domain VARCHAR(255) NOT NULL UNIQUE,status ENUM('active','disabled') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE links(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,domain_id BIGINT UNSIGNED NULL,short_code VARCHAR(32) NOT NULL UNIQUE,destination_url TEXT NOT NULL,title VARCHAR(255),description TEXT,image_url VARCHAR(2048),status ENUM('active','disabled','deleted') NOT NULL DEFAULT 'active',click_count BIGINT UNSIGNED NOT NULL DEFAULT 0,bot_click_count BIGINT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL,updated_at DATETIME NULL,INDEX(user_id),INDEX(status),CONSTRAINT fk_links_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_links_domain FOREIGN KEY(domain_id) REFERENCES domains(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE click_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,link_id BIGINT UNSIGNED NOT NULL,is_bot TINYINT(1) NOT NULL DEFAULT 0,user_agent VARCHAR(1000),ip_hash CHAR(64),referer VARCHAR(2048),created_at DATETIME NOT NULL,INDEX(link_id,created_at),CONSTRAINT fk_click_link FOREIGN KEY(link_id) REFERENCES links(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE activity_log(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,metadata JSON,created_at DATETIME NOT NULL,INDEX(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;